@pytest.mark.parametrize(("prop", "raw_css", "expected"), VALID_PROPERTY_CASES)
def test_wpt_css_properties_valid(prop: str, raw_css: str, expected: str) -> None:
    got = canonicalize(prop, raw_css, options=CSSOM_OPTS)
    assert got == expected
    assert canonicalize(prop, got, options=CSSOM_OPTS) == expected


@pytest.mark.parametrize(("prop", "raw_css"), INVALID_PROPERTY_CASES)
def test_wpt_css_properties_invalid(prop: str, raw_css: str) -> None:
    with pytest.raises(StixisError):
        canonicalize(prop, raw_css, options=CSSOM_OPTS)
